      'Als tansanisch-stämmiger, in Arusha ansässiger Anbieter, der gerade unsere Kenia-Route aufbaut, gestalten wir diese Route nach demselben Prinzip wie unsere Ostafrika-Reisepläne: maßgeschneidert auf Ihre Reisedaten, durchgehend privat und geführt von professionellen, zertifizierten Guides.',
